   239:  border-color: transparent;
   240:}
   241:
   242:.care-primary-button.care-stitched::after {
   243:  inset: 5px;
   244:  border-color: rgba(255, 255, 255, 0.45);
   245:  border-radius: calc(var(--care-radius) - 6px);
   246:}
   247:
   248:.care-primary-button:hover {
   249:  transform: translateY(-3px);
   250:}
   251:
   252:.care-text-link {
   253:  display: inline-flex;
   254:  min-height: var(--care-touch);
   255:  align-items: center;
   256:  color: var(--care-forest-800);
   257:  font-weight: 700;
   258:  text-decoration: underline;
   259:  text-underline-offset: 4px;
   260:}
   261:
   262:/* ── Header ── */
   263:.care-header {
   264:  position: relative;
   265:  z-index: 20;
   266:  padding: 10px var(--care-gutter);
   267:  background: var(--care-forest-950);
   268:  box-shadow: 0 8px 30px rgba(19, 54, 38, 0.16);
   269:  color: var(--care-on-dark);
   270:}
   271:
   272:.care-header__inner {
   273:  display: grid;
   274:  max-width: var(--care-max);
   275:  margin: 0 auto;
   276:  grid-template-areas:
   277:    "brand actions"
   278:    "nav nav";
   279:  grid-template-columns: auto minmax(0, 1fr);
   280:  align-items: center;
   281:  gap: 10px 16px;
   282:}
   283:
   284:.care-header--public .care-header__inner {
   285:  display: flex;
   286:  justify-content: space-between;
   287:}
   288:
   289:.care-header__inner > .care-brand { grid-area: brand; }
   290:
   291:.care-header__actions {
   292:  display: flex;
   293:  min-width: 0;
   294:  grid-area: actions;
   295:  justify-content: flex-end;
   296:  align-items: center;
   297:  gap: 12px;
   298:}
   299:
   300:.care-profile {
   301:  display: flex;
   302:  min-width: 0;
   303:  align-items: center;
   304:  gap: 8px;
   305:  font-size: var(--care-text-sm);
   306:  font-weight: 600;
   307:}
   308:
   309:.care-profile__initial {
   310:  display: grid;
   311:  width: 34px;
   312:  height: 34px;
   313:  flex: 0 0 auto;
   314:  place-items: center;
   315:  border-radius: 50%;
   316:  background: var(--care-orange);
   317:  color: var(--care-on-dark);
   318:  font-weight: 700;
   319:}
   320:
   321:.care-profile__name {
   322:  overflow: hidden;
   323:  text-overflow: ellipsis;
   324:  white-space: nowrap;
   325:}
   326:
   327:.care-nav {
   328:  display: grid;
   329:  padding: 4px;
   330:  grid-area: nav;
   331:  grid-template-columns: repeat(3, minmax(0, 1fr));
   332:  border: 1px solid var(--care-glass);
   333:  border-radius: var(--care-radius-md);
   334:  background: var(--care-glass);
   335:  gap: 3px;
   336:}
   337:
   338:.care-nav__item {
   339:  display: grid;
   340:  min-height: var(--care-touch);
   341:  padding: 4px 8px;
   342:  place-items: center;
   343:  border-radius: var(--care-radius-sm);
   344:  color: var(--care-on-dark-soft);
   345:  font-size: var(--care-text-sm);
   346:  font-weight: 700;
   347:  line-height: 1.2;
   348:  text-align: center;
   349:}
   350:
   351:.care-nav__item:hover {
   352:  color: var(--care-on-dark);
   353:}
   354:
   355:.care-nav__item[aria-current="page"] {
   356:  background: var(--care-cream-50);
   357:  box-shadow: 0 5px 16px rgba(9, 39, 25, 0.2);
   358:  color: var(--care-forest-900);
   359:}
   360:
   361:@media (min-width: 900px) {
   362:  /* Sticky only where the one-row header is short; on phones it scrolls away. */
   363:  .care-header {
   364:    position: sticky;
   365:    top: 0;
   366:  }
   367:
   368:  .care-header__inner {
   369:    grid-template-areas: "brand nav actions";
   370:    grid-template-columns: 1fr auto 1fr;
   371:  }
   372:
   373:  .care-nav {
   374:    display: flex;
   375:  }
   376:
   377:  .care-nav__item {
   378:    padding: 0 18px;
   379:  }
   380:}
   381:
   382:/* ── Offline notice and notes ── */
   383:.care-offline {
   384:  width: min(100% - 2 * var(--care-gutter), var(--care-max));
   385:  margin: 16px auto 0;
   386:}
   387:
   388:.care-notice {
   389:  margin-top: 16px;
   390:  padding: 14px 16px;
   391:  border-radius: var(--care-radius-sm);
   392:  background: rgba(216, 223, 191, 0.5);
   393:  color: var(--care-ink);
   394:  font-size: var(--care-text-sm);
   395:}
   396:
   397:.care-offline .care-notice {
   398:  margin-top: 0;
   399:}
   400:
   401:.care-notice--warm {
   402:  background: var(--care-yellow-soft);
   403:}
   404:
   405:.care-live {
   406:  min-height: 1.5em;
   407:  margin-top: 10px;
   408:  color: var(--care-forest-800);
   409:  font-size: var(--care-text-sm);
   410:  font-weight: 600;
   411:}
   412:
   413:/* ── Landing ── */
   414:.care-hero {
   415:  position: relative;
   416:  display: grid;
   417:  min-height: clamp(540px, 82dvh, 760px);
   418:  padding: clamp(40px, 8vh, 96px) var(--care-gutter);
   419:  place-items: center;
   420:  overflow: hidden;
   421:  background: var(--care-forest-900);
   422:  color: var(--care-on-dark);
   423:}
   424:
   425:.care-hero::after {
   426:  position: absolute;
   427:  inset: 0;
   428:  background: var(--care-hero-shade);
   429:  content: "";
   430:}
   431:
   432:.care-hero__scene {
   433:  position: absolute;
   434:  inset: 0;
   435:  width: 100%;
   436:  height: 100%;
   437:  object-fit: cover;
   438:  object-position: center bottom;
   439:}
   440:
   441:.care-hero__copy {
   442:  position: relative;
   443:  z-index: 1;
   444:  display: flex;
   445:  max-width: 650px;
   446:  align-items: center;
   447:  flex-direction: column;
   448:  text-align: center;
   449:}
   450:
   451:.care-hero h1 {
   452:  margin-top: 14px;
   453:  font-size: var(--care-text-hero-title);
   454:  line-height: 1;
   455:  letter-spacing: -0.045em;
   456:}
   457:
   458:.care-hero__intro {
   459:  max-width: 585px;
   460:  margin-top: 24px;
   461:  color: var(--care-on-dark-soft);
   462:  font-size: var(--care-text-lg);
   463:  line-height: 1.65;
   464:}
   465:
   466:.care-hero .care-primary-button {
   467:  margin-top: 32px;
   468:}
   469:
   470:.care-hero .care-eyebrow {
   471:  margin-top: 16px;
   472:}
   473:
   474:.care-dog {
   475:  height: auto;
   476:  object-fit: contain;
   477:  filter: drop-shadow(0 12px 18px rgba(10, 30, 20, 0.35));
   478:}
   479:
   480:.care-dog--large {
   481:  width: clamp(120px, 16vw, 170px);
   482:}
   483:
   484:.care-dog--small {
   485:  position: relative;
   486:  z-index: 1;
   487:  width: clamp(72px, 12vw, 120px);
   488:  flex: 0 0 auto;
   489:}
   490:
   491:.care-support {
   492:  padding: clamp(56px, 9vw, 96px) var(--care-gutter) clamp(64px, 10vw, 112px);
   493:  text-align: center;
   494:}
   495:
   496:.care-support h2 {
   497:  margin-top: 10px;
   498:  font-size: clamp(2rem, 1.5rem + 2.2vw, 3.25rem);
   499:  line-height: 1.05;
   500:  letter-spacing: -0.035em;
   501:}
   502:
   503:.care-support__intro {
   504:  max-width: 650px;
   505:  margin: 18px auto 0;
   506:  color: var(--care-muted);
   507:  font-size: var(--care-text-lg);
   508:  line-height: 1.6;
   509:}
   510:
   511:.care-features {
   512:  display: grid;
   513:  max-width: var(--care-max);
   514:  margin: clamp(32px, 5vw, 56px) auto 0;
   515:  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
   516:  gap: var(--care-gap);
   517:  text-align: left;
   518:}
   519:
   520:.care-feature {
   521:  padding: clamp(28px, 3.5vw, 38px);
   522:  border-radius: var(--care-radius);
   523:  background: var(--care-cream-50);
   524:  box-shadow: var(--care-shadow);
   525:}
   526:
   527:.care-feature h3 {
   528:  margin-top: 24px;
   529:  font-size: 1.3rem;
   530:}
   531:
   532:.care-feature p {
   533:  margin-top: 10px;
   534:  color: var(--care-muted);
   535:  line-height: 1.65;
   536:}
   537:
   538:.care-token {
   539:  display: grid;
   540:  width: 54px;
   541:  height: 54px;
   542:  place-items: center;
   543:  border-radius: 18px;
   544:  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.3), 0 7px 15px rgba(35, 68, 46, 0.12);
   545:  color: var(--care-forest-900);
   546:  transform: rotate(-4deg);
   547:}
   548:
   549:.care-token--moss { background: var(--care-moss-soft); }
   550:.care-token--rose { background: var(--care-rose-soft); color: var(--care-rose-ink); transform: rotate(4deg); }
   551:.care-token--sun { background: var(--care-yellow-soft); color: var(--care-orange-ink); transform: rotate(-2deg); }
   552:
   553:/* ── Sign-in picker ── */
   554:.care-signin {
   555:  display: grid;
   556:  min-height: 70dvh;
   557:  padding: clamp(32px, 7vw, 80px) var(--care-gutter);
   558:  place-items: center;
   559:  background-color: var(--care-forest-900);
   560:  background-image: linear-gradient(var(--care-hero-shade), var(--care-hero-shade)), var(--care-garden-image);
   561:  background-position: center bottom;
   562:  background-size: cover;
   563:}
   564:
   565:.care-signin__card {
   566:  width: min(100%, 560px);
   567:  padding: clamp(24px, 5vw, 44px);
   568:  border-radius: var(--care-radius);
   569:  background: var(--care-cream-50);
   570:  box-shadow: var(--care-shadow);
   571:}
   572:
   573:.care-signin h1 {
   574:  margin-top: 8px;
   575:  font-size: clamp(1.75rem, 1.4rem + 1.6vw, 2.4rem);
   576:  line-height: 1.1;
   577:  letter-spacing: -0.03em;
   578:}
   579:
   580:.care-signin__demo {
   581:  margin-top: 10px;
   582:  color: var(--care-muted);
   583:}
   584:
   585:.care-personas {
   586:  position: relative;
   587:  z-index: 1;
   588:  display: grid;
   589:  margin: 24px 0 12px;
   590:  gap: 12px;
   591:}
   592:
   593:.care-persona {
   594:  display: grid;
   595:  width: 100%;
   596:  min-height: 72px;
   597:  padding: 12px 16px;
   598:  grid-template-columns: 46px minmax(0, 1fr) auto;
   599:  align-items: center;
   600:  gap: 14px;
   601:  border: 1px solid var(--care-cream-300);
   602:  border-radius: var(--care-radius-md);
   603:  background: #ffffff;
   604:  cursor: pointer;
   605:  text-align: left;
   606:  transition: transform 180ms ease;
   607:}
   608:
   609:.care-persona:hover {
   610:  border-color: var(--care-forest-700);
   611:  transform: translateY(-2px);
   612:}
   613:
   614:.care-persona__text strong,
   615:.care-persona__text span {
   616:  display: block;
   617:}
   618:
   619:.care-persona__text strong {
   620:  font-size: var(--care-text-lg);
   621:}
   622:
   623:.care-persona__text span {
   624:  color: var(--care-muted);
   625:  font-size: var(--care-text-sm);
   626:}
   627:
   628:.care-persona__arrow {
   629:  color: var(--care-forest-700);
   630:  font-size: 1.3rem;
   631:}
   632:
   633:.care-signin .care-text-link {
   634:  position: relative;
   635:  z-index: 1;
   636:}
   637:
   638:/* ── Signed-in page frame ── */
   639:.care-content {
   640:  width: min(100% - 2 * var(--care-gutter), var(--care-max));
   641:  margin: 0 auto;
   642:  padding: clamp(16px, 3vw, 40px) 0 clamp(32px, 6vw, 72px);
   643:}
   644:
   645:.care-welcome {
   646:  position: relative;
   647:  display: flex;
   648:  min-height: clamp(140px, 20vw, 188px);
   649:  padding: clamp(20px, 4vw, 34px) clamp(20px, 4vw, 45px);
   650:  align-items: center;
   651:  justify-content: space-between;
   652:  gap: 16px;
   653:  overflow: hidden;
   654:  border-radius: var(--care-radius);
   655:  background-color: var(--care-forest-900);
   656:  background-image: var(--care-garden-image);
   657:  background-position: center 60%;
   658:  background-size: cover;
   659:  background-blend-mode: multiply;
   660:  box-shadow: var(--care-shadow);
   661:  color: var(--care-on-dark);
   662:}
   663:
   664:.care-welcome__copy {
   665:  position: relative;
   666:  z-index: 1;
   667:  min-width: 0;
   668:}
   669:
   670:.care-welcome h1 {
   671:  margin-top: 8px;
   672:  font-size: var(--care-text-page-title);
   673:  line-height: 1.05;
   674:  letter-spacing: -0.035em;
   675:}
   676:
   677:.care-welcome__copy > p:last-child {
   678:  margin-top: 10px;
   679:  color: var(--care-on-dark-soft);
   680:}
   681:
   682:.care-grid {
   683:  display: grid;
   684:  margin-top: var(--care-gap);
   685:  grid-template-columns: minmax(0, 1fr);
   686:  gap: var(--care-gap);
   687:}
   688:
   689:@media (min-width: 900px) {
   690:  .care-grid {
   691:    grid-template-columns: repeat(2, minmax(0, 1fr));
   692:  }
   693:
   694:  .care-grid--alerts {
   695:    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
   696:    align-items: start;
   697:  }
   698:}
   699:
   700:/* ── Cards ── */
   701:.care-card {
   702:  position: relative;
   703:  min-width: 0;
   704:  padding: var(--care-card-pad);
   705:  border: 1px solid var(--care-edge);
   706:  border-radius: var(--care-radius);
   707:  background: var(--care-cream-50);
   708:  box-shadow: var(--care-shadow);
   709:}
   710:
   711:.care-card__heading {
   712:  position: relative;
   713:  z-index: 1;
   714:  display: flex;
   715:  align-items: flex-start;
   716:  justify-content: space-between;
   717:  flex-wrap: wrap;
   718:  gap: 8px 16px;
   719:}
   720:
   721:.care-card__heading h2 {
   722:  margin-top: 6px;
   723:  font-size: var(--care-text-card-title);
   724:  line-height: 1.15;
   725:  letter-spacing: -0.02em;
   726:}
   727:
   728:.care-card__meta {
   729:  color: var(--care-muted);
   730:  font-size: var(--care-text-xs);
   731:}
   732:
   733:.care-badge {
   734:  display: inline-flex;
   735:  min-height: 31px;
   736:  padding: 0 12px;
   737:  align-items: center;
   738:  border-radius: 999px;
   739:  font-size: var(--care-text-xs);
   740:  font-weight: 700;
   741:  white-space: nowrap;
   742:}
   743:
   744:.care-badge--moss { background: var(--care-moss-soft); color: var(--care-forest-900); }
   745:.care-badge--rose { background: var(--care-rose-soft); color: var(--care-rose-ink); }
   746:
   747:/* Today ring */
   748:.care-progress {
   749:  display: flex;
   750:  min-height: 200px;
   751:  padding-top: 20px;
   752:  align-items: center;
   753:  justify-content: center;
   754:  flex-wrap: wrap;
   755:  gap: 20px 40px;
   756:}
   757:
   758:.care-ring {
   759:  display: grid;
   760:  width: clamp(128px, 32vw, 154px);
   761:  aspect-ratio: 1;
   762:  flex: 0 0 auto;
   763:  place-items: center;
   764:  border-radius: 50%;
   765:  background: conic-gradient(var(--care-orange) 0 var(--care-ring-fill), var(--care-cream-200) 0 100%);
   766:  box-shadow: 0 12px 28px rgba(78, 57, 37, 0.13);
   767:}
   768:
   769:.care-ring__center {
   770:  display: flex;
   771:  width: 73%;
   772:  aspect-ratio: 1;
   773:  align-items: center;
   774:  justify-content: center;
   775:  flex-direction: column;
   776:  border-radius: 50%;
   777:  background: var(--care-cream-50);
   778:}
   779:
   780:.care-ring strong {
   781:  color: var(--care-forest-900);
   782:  font-size: 1.4rem;
   783:}
   784:
   785:.care-ring span {
   786:  color: var(--care-muted);
   787:  font-size: var(--care-text-sm);
   788:}
   789:
   790:.care-progress__copy {
   791:  max-width: 220px;
   792:  text-align: center;
   793:}
   794:
   795:.care-progress__copy strong {
   796:  font-size: var(--care-text-lg);
   797:  line-height: 1.3;
   798:}
   799:
   800:.care-progress__copy p {
   801:  margin-top: 8px;
   802:  color: var(--care-muted);
   803:  font-size: var(--care-text-sm);
   804:  line-height: 1.55;
   805:}
   806:
   807:@media (min-width: 520px) {
   808:  .care-progress__copy { text-align: left; }
   809:}
   810:
   811:/* Streak hearts: a rotated square plus two circles, knitted look */
   812:.care-hearts {
   813:  --care-heart-size: clamp(18px, 4.6vw, 32px);
   814:  display: grid;
   815:  min-height: 180px;
   816:  padding-top: 12px;
   817:  align-items: center;
   818:  grid-template-columns: repeat(7, minmax(0, 1fr));
   819:  gap: 4px;
   820:}
   821:
   822:.care-hearts__day {
   823:  display: flex;
   824:  align-items: center;
   825:  flex-direction: column;
   826:  gap: calc(var(--care-heart-size) * 0.55);
   827:  color: var(--care-muted);
   828:  font-size: var(--care-text-xs);
   829:  font-weight: 700;
   830:}
   831:
   832:.care-heart {
   833:  position: relative;
   834:  display: block;
   835:  width: var(--care-heart-size);
   836:  height: var(--care-heart-size);
   837:  margin-top: calc(var(--care-heart-size) * 0.5);
   838:  border-radius: 6px 9px 6px 9px;
   839:  background: var(--care-cream-200);
   840:  transform: rotate(45deg);
   841:  animation: care-heart-pop 500ms cubic-bezier(0.2, 0.8, 0.3, 1.3) both;
   842:  animation-delay: var(--care-heart-delay, 0ms);
   843:}
   844:
   845:.care-heart::before,
   846:.care-heart::after {
   847:  position: absolute;
   848:  width: 100%;
   849:  height: 100%;
   850:  border-radius: 50%;
   851:  background: inherit;
   852:  content: "";
   853:}
   854:
   855:.care-heart::before { left: -50%; }
   856:.care-heart::after { top: -50%; }
   857:
   858:.care-heart.is-filled {
   859:  background: var(--care-rose);
   860:  box-shadow: 0 7px 13px rgba(104, 48, 49, 0.18);
   861:}
   862:
   863:@keyframes care-heart-pop {
   864:  from { opacity: 0; transform: rotate(45deg) scale(0.65); }
   865:  to { opacity: 1; transform: rotate(45deg) scale(1); }
   866:}
   867:
   868:/* Caring moments */
   869:.care-moments {
   870:  margin-top: 20px;
   871:}
   872:
   873:.care-moment {
   874:  display: grid;
   875:  padding: 14px 0;
   876:  grid-template-columns: 44px minmax(0, 1fr);
   877:  align-items: center;
   878:  gap: 14px;
   879:  border-top: 1px solid var(--care-cream-200);
   880:}
   881:
   882:.care-moment__icon {
   883:  display: grid;
   884:  width: 44px;
   885:  height: 44px;
   886:  place-items: center;
   887:  border-radius: 15px;
   888:  background: var(--care-rose-soft);
   889:  color: var(--care-rose-ink);
   890:}
   891:
   892:.care-moment__icon--check_in {
   893:  background: var(--care-orange-soft);
   894:  color: var(--care-orange-ink);
   895:}
   896:
