    38:  --care-yellow-soft: #f2dfad;
    39:  /* Call to action (darker than the accents so white text passes AA) */
    40:  --care-cta-from: #b5562d;
    41:  --care-cta-to: #a9545a;
    42:  /* Overlays */
    43:  --care-hero-shade: rgba(14, 53, 35, 0.7);
    44:  --care-footer-shade: rgba(21, 63, 44, 0.8);
    45:  --care-glass: rgba(255, 255, 255, 0.08);
    46:  --care-glass-strong: rgba(255, 255, 255, 0.14);
    47:  --care-stitch: rgba(90, 75, 53, 0.24);
    48:  --care-edge: rgba(91, 75, 49, 0.12);
    49:  /* Type */
    50:  --care-font: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
    51:  --care-text-xs: 0.75rem;
    52:  --care-text-sm: 0.875rem;
    53:  --care-text-md: 1rem;
    54:  --care-text-lg: 1.125rem;
    55:  --care-text-card-title: clamp(1.25rem, 1.1rem + 0.6vw, 1.45rem);
    56:  --care-text-page-title: clamp(1.9rem, 1.4rem + 2.4vw, 3rem);
    57:  --care-text-hero-title: clamp(2.5rem, 1.6rem + 4.4vw, 4.5rem);
    58:  /* Shape and space */
    59:  --care-radius: 26px;
    60:  --care-radius-md: 18px;
    61:  --care-radius-sm: 14px;
    62:  --care-gutter: clamp(16px, 4vw, 32px);
    63:  --care-gap: clamp(16px, 2.4vw, 24px);
    64:  --care-card-pad: clamp(20px, 3vw, 32px);
    65:  --care-max: 1180px;
    66:  --care-touch: 44px;
    67:  /* Depth */
    68:  --care-shadow: 0 22px 60px rgba(39, 69, 49, 0.13), 0 3px 10px rgba(39, 69, 49, 0.08);
    69:  --care-shadow-lift: 0 14px 30px rgba(71, 38, 25, 0.22);
    70:  --care-focus: var(--care-yellow);
    71:  /* Motion */
    72:  --care-ease: cubic-bezier(0.22, 1, 0.36, 1);
    73:}
    74:
    75:html:has(.care-root) {
