   140:  color: var(--care-forest-700);
   141:  font-size: var(--care-text-xs);
   142:  font-weight: 700;
   143:  letter-spacing: 0.14em;
   144:  line-height: 1.3;
   145:  text-transform: uppercase;
   146:}
   147:
   148:.care-eyebrow--light {
   149:  color: var(--care-yellow-soft);
   150:}
   151:
   152:.care-stitched {
   153:  position: relative;
   154:  border: 1px solid var(--care-edge);
   155:}
   156:
   157:.care-stitched::after {
   158:  position: absolute;
   159:  inset: 7px;
   160:  border: 1px dashed var(--care-stitch);
   161:  border-radius: calc(var(--care-radius) - 8px);
   162:  content: "";
   163:  pointer-events: none;
   164:}
   165:
   166:.care-hint {
   167:  margin-top: 12px;
   168:  color: var(--care-muted);
   169:  font-size: var(--care-text-sm);
   170:}
   171:
   172:.care-empty {
   173:  margin-top: 20px;
   174:  color: var(--care-muted);
   175:  font-size: var(--care-text-sm);
   176:}
   177:
   178:/* ── Buttons and links ── */
   179:.care-brand {
   180:  display: inline-flex;
   181:  min-height: var(--care-touch);
   182:  align-items: center;
   183:  gap: 10px;
   184:  color: inherit;
   185:  font-size: 1.3rem;
   186:  font-weight: 800;
   187:  letter-spacing: -0.01em;
   188:}
   189:
   190:button.care-brand {
   191:  cursor: pointer;
   192:}
   193:
   194:.care-brand__paw {
   195:  fill: currentColor;
   196:  stroke: none;
   197:  color: var(--care-yellow-soft);
   198:}
   199:
   200:.care-ghost-button {
   201:  display: inline-flex;
   202:  min-height: var(--care-touch);
   203:  padding: 0 16px;
   204:  align-items: center;
   205:  border: 1px solid rgba(255, 255, 255, 0.24);
   206:  border-radius: var(--care-radius-sm);
   207:  background: var(--care-glass);
   208:  color: var(--care-on-dark);
   209:  cursor: pointer;
   210:  font-size: var(--care-text-sm);
   211:  font-weight: 700;
   212:  white-space: nowrap;
   213:  transition: transform 180ms ease;
   214:}
   215:
   216:.care-ghost-button:hover {
   217:  background: var(--care-glass-strong);
   218:  transform: translateY(-1px);
   219:}
   220:
   221:.care-primary-button {
   222:  position: relative;
   223:  display: inline-flex;
   224:  min-height: 58px;
   225:  padding: 0 28px;
   226:  align-items: center;
   227:  gap: 18px;
   228:  border-radius: var(--care-radius);
   229:  background: linear-gradient(135deg, var(--care-cta-from), var(--care-cta-to));
   230:  box-shadow: var(--care-shadow-lift);
   231:  color: var(--care-on-dark);
   232:  cursor: pointer;
   233:  font-size: var(--care-text-lg);
   234:  font-weight: 700;
   235:  transition: transform 200ms ease;
   236:}
   237:
   238:.care-primary-button.care-stitched {
   239:  border-color: transparent;
   240:}
   241:
   242:.care-primary-button.care-stitched::after {
   243:  inset: 5px;
   244:  border-color: rgba(255, 255, 255, 0.45);
   245:  border-radius: calc(var(--care-radius) - 6px);
   246:}
   247:
   248:.care-primary-button:hover {
   249:  transform: translateY(-3px);
   250:}
   251:
   252:.care-text-link {
   253:  display: inline-flex;
   254:  min-height: var(--care-touch);
   255:  align-items: center;
   256:  color: var(--care-forest-800);
   257:  font-weight: 700;
   258:  text-decoration: underline;
   259:  text-underline-offset: 4px;
   260:}
   261:
   262:/* ── Header ── */
   263:.care-header {
   264:  position: relative;
   265:  z-index: 20;
   266:  padding: 10px var(--care-gutter);
   267:  background: var(--care-forest-950);
   268:  box-shadow: 0 8px 30px rgba(19, 54, 38, 0.16);
   269:  color: var(--care-on-dark);
   270:}
   271:
   272:.care-header__inner {
   273:  display: grid;
   274:  max-width: var(--care-max);
   275:  margin: 0 auto;
   276:  grid-template-areas:
   277:    "brand actions"
   278:    "nav nav";
   279:  grid-template-columns: auto minmax(0, 1fr);
   280:  align-items: center;
   281:  gap: 10px 16px;
   282:}
   283:
   284:.care-header--public .care-header__inner {
   285:  display: flex;
   286:  justify-content: space-between;
   287:}
   288:
   289:.care-header__inner > .care-brand { grid-area: brand; }
   290:
   291:.care-header__actions {
   292:  display: flex;
   293:  min-width: 0;
   294:  grid-area: actions;
   295:  justify-content: flex-end;
   296:  align-items: center;
   297:  gap: 12px;
   298:}
   299:
   300:.care-profile {
   301:  display: flex;
   302:  min-width: 0;
   303:  align-items: center;
   304:  gap: 8px;
   305:  font-size: var(--care-text-sm);
   306:  font-weight: 600;
   307:}
   308:
   309:.care-profile__initial {
   310:  display: grid;
   311:  width: 34px;
   312:  height: 34px;
   313:  flex: 0 0 auto;
   314:  place-items: center;
   315:  border-radius: 50%;
   316:  background: var(--care-orange);
   317:  color: var(--care-on-dark);
   318:  font-weight: 700;
   319:}
   320:
   321:.care-profile__name {
   322:  overflow: hidden;
   323:  text-overflow: ellipsis;
   324:  white-space: nowrap;
   325:}
   326:
   327:.care-nav {
   328:  display: grid;
   329:  padding: 4px;
   330:  grid-area: nav;
   331:  grid-template-columns: repeat(3, minmax(0, 1fr));
   332:  border: 1px solid var(--care-glass);
   333:  border-radius: var(--care-radius-md);
   334:  background: var(--care-glass);
   335:  gap: 3px;
   336:}
   337:
   338:.care-nav__item {
   339:  display: grid;
   340:  min-height: var(--care-touch);
   341:  padding: 4px 8px;
   342:  place-items: center;
   343:  border-radius: var(--care-radius-sm);
   344:  color: var(--care-on-dark-soft);
   345:  font-size: var(--care-text-sm);
   346:  font-weight: 700;
   347:  line-height: 1.2;
   348:  text-align: center;
   349:}
   350:
   351:.care-nav__item:hover {
   352:  color: var(--care-on-dark);
   353:}
   354:
   355:.care-nav__item[aria-current="page"] {
   356:  background: var(--care-cream-50);
   357:  box-shadow: 0 5px 16px rgba(9, 39, 25, 0.2);
   358:  color: var(--care-forest-900);
   359:}
   360:
   361:@media (min-width: 900px) {
   362:  /* Sticky only where the one-row header is short; on phones it scrolls away. */
   363:  .care-header {
   364:    position: sticky;
   365:    top: 0;
   366:  }
   367:
   368:  .care-header__inner {
   369:    grid-template-areas: "brand nav actions";
   370:    grid-template-columns: 1fr auto 1fr;
   371:  }
   372:
   373:  .care-nav {
   374:    display: flex;
   375:  }
   376:
   377:  .care-nav__item {
   378:    padding: 0 18px;
   379:  }
   380:}
   381:
   382:/* ── Offline notice and notes ── */
   383:.care-offline {
   384:  width: min(100% - 2 * var(--care-gutter), var(--care-max));
   385:  margin: 16px auto 0;
   386:}
   387:
   388:.care-notice {
   389:  margin-top: 16px;
   390:  padding: 14px 16px;
   391:  border-radius: var(--care-radius-sm);
   392:  background: rgba(216, 223, 191, 0.5);
   393:  color: var(--care-ink);
   394:  font-size: var(--care-text-sm);
   395:}
   396:
   397:.care-offline .care-notice {
   398:  margin-top: 0;
   399:}
   400:
   401:.care-notice--warm {
   402:  background: var(--care-yellow-soft);
   403:}
   404:
   405:.care-live {
   406:  min-height: 1.5em;
   407:  margin-top: 10px;
   408:  color: var(--care-forest-800);
   409:  font-size: var(--care-text-sm);
   410:  font-weight: 600;
   411:}
   412:
   413:/* ── Landing ── */
   414:.care-hero {
   415:  position: relative;
   416:  display: grid;
   417:  min-height: clamp(540px, 82dvh, 760px);
   418:  padding: clamp(40px, 8vh, 96px) var(--care-gutter);
   419:  place-items: center;
   420:  overflow: hidden;
   421:  background: var(--care-forest-900);
   422:  color: var(--care-on-dark);
   423:}
   424:
   425:.care-hero::after {
   426:  position: absolute;
   427:  inset: 0;
   428:  background: var(--care-hero-shade);
   429:  content: "";
   430:}
   431:
   432:.care-hero__scene {
   433:  position: absolute;
   434:  inset: 0;
   435:  width: 100%;
   436:  height: 100%;
   437:  object-fit: cover;
   438:  object-position: center bottom;
   439:}
   440:
   441:.care-hero__copy {
   442:  position: relative;
   443:  z-index: 1;
   444:  display: flex;
   445:  max-width: 650px;
   446:  align-items: center;
   447:  flex-direction: column;
   448:  text-align: center;
   449:}
   450:
   451:.care-hero h1 {
   452:  margin-top: 14px;
   453:  font-size: var(--care-text-hero-title);
   454:  line-height: 1;
   455:  letter-spacing: -0.045em;
   456:}
   457:
   458:.care-hero__intro {
   459:  max-width: 585px;
   460:  margin-top: 24px;
   461:  color: var(--care-on-dark-soft);
   462:  font-size: var(--care-text-lg);
   463:  line-height: 1.65;
   464:}
   465:
   466:.care-hero .care-primary-button {
   467:  margin-top: 32px;
   468:}
   469:
   470:.care-hero .care-eyebrow {
   471:  margin-top: 16px;
   472:}
   473:
   474:.care-dog {
   475:  height: auto;
   476:  object-fit: contain;
   477:  filter: drop-shadow(0 12px 18px rgba(10, 30, 20, 0.35));
   478:}
   479:
   480:.care-dog--large {
   481:  width: clamp(120px, 16vw, 170px);
   482:}
   483:
   484:.care-dog--small {
   485:  position: relative;
   486:  z-index: 1;
   487:  width: clamp(72px, 12vw, 120px);
   488:  flex: 0 0 auto;
   489:}
   490:
   491:.care-support {
   492:  padding: clamp(40px, 7vw, 72px) var(--care-gutter) clamp(48px, 8vw, 96px);
   493:}
   494:
   495:.care-features {
   496:  display: grid;
   497:  max-width: var(--care-max);
   498:  margin: 0 auto;
   499:  grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
   500:  gap: var(--care-gap);
   501:  text-align: left;
   502:}
   503:
   504:.care-feature {
   505:  padding: clamp(28px, 3.5vw, 38px);
   506:  border-radius: var(--care-radius);
   507:  background: var(--care-cream-50);
   508:  box-shadow: var(--care-shadow);
   509:}
   510:
   511:.care-feature h2 {
   512:  margin-top: 24px;
   513:  font-size: 1.3rem;
   514:  line-height: 1.2;
   515:  letter-spacing: -0.01em;
   516:}
   517:
   518:.care-feature p {
   519:  margin-top: 10px;
   520:  color: var(--care-muted);
   521:  line-height: 1.65;
   522:}
   523:
   524:.care-token {
   525:  display: grid;
   526:  width: 54px;
   527:  height: 54px;
   528:  place-items: center;
   529:  border-radius: 18px;
   530:  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.3), 0 7px 15px rgba(35, 68, 46, 0.12);
   531:  color: var(--care-forest-900);
   532:  transform: rotate(-4deg);
   533:}
   534:
   535:.care-token--moss { background: var(--care-moss-soft); }
   536:.care-token--rose { background: var(--care-rose-soft); color: var(--care-rose-ink); transform: rotate(4deg); }
   537:.care-token--sun { background: var(--care-yellow-soft); color: var(--care-orange-ink); transform: rotate(-2deg); }
   538:
   539:/* ── Sign-in picker ── */
   540:.care-signin {
   541:  display: grid;
   542:  min-height: 70dvh;
   543:  padding: clamp(32px, 7vw, 80px) var(--care-gutter);
   544:  place-items: center;
   545:  background-color: var(--care-forest-900);
   546:  background-image: linear-gradient(var(--care-hero-shade), var(--care-hero-shade)), var(--care-garden-image);
   547:  background-position: center bottom;
   548:  background-size: cover;
   549:}
   550:
   551:.care-signin__card {
   552:  width: min(100%, 560px);
   553:  padding: clamp(24px, 5vw, 44px);
   554:  border-radius: var(--care-radius);
   555:  background: var(--care-cream-50);
   556:  box-shadow: var(--care-shadow);
   557:}
   558:
   559:.care-signin h1 {
   560:  margin-top: 8px;
   561:  font-size: clamp(1.75rem, 1.4rem + 1.6vw, 2.4rem);
   562:  line-height: 1.1;
   563:  letter-spacing: -0.03em;
   564:}
   565:
   566:.care-signin__demo {
   567:  margin-top: 10px;
   568:  color: var(--care-muted);
   569:}
   570:
   571:.care-personas {
   572:  position: relative;
   573:  z-index: 1;
   574:  display: grid;
   575:  margin: 24px 0 12px;
   576:  gap: 12px;
   577:}
   578:
   579:.care-persona {
   580:  display: grid;
   581:  width: 100%;
   582:  min-height: 72px;
   583:  padding: 12px 16px;
   584:  grid-template-columns: 46px minmax(0, 1fr) auto;
   585:  align-items: center;
   586:  gap: 14px;
   587:  border: 1px solid var(--care-cream-300);
   588:  border-radius: var(--care-radius-md);
   589:  background: #ffffff;
   590:  cursor: pointer;
   591:  text-align: left;
   592:  transition: transform 180ms ease;
   593:}
   594:
   595:.care-persona:hover {
   596:  border-color: var(--care-forest-700);
   597:  transform: translateY(-2px);
   598:}
   599:
   600:.care-persona__text strong,
   601:.care-persona__text span {
   602:  display: block;
   603:}
   604:
   605:.care-persona__text strong {
   606:  font-size: var(--care-text-lg);
   607:}
   608:
   609:.care-persona__text span {
   610:  color: var(--care-muted);
   611:  font-size: var(--care-text-sm);
   612:}
   613:
   614:.care-persona__arrow {
   615:  color: var(--care-forest-700);
   616:  font-size: 1.3rem;
   617:}
   618:
   619:.care-signin .care-text-link {
   620:  position: relative;
   621:  z-index: 1;
   622:}
   623:
   624:/* ── Signed-in page frame ── */
   625:.care-content {
   626:  width: min(100% - 2 * var(--care-gutter), var(--care-max));
   627:  margin: 0 auto;
   628:  padding: clamp(16px, 3vw, 40px) 0 clamp(32px, 6vw, 72px);
   629:}
   630:
   631:.care-welcome {
   632:  position: relative;
   633:  display: flex;
   634:  min-height: clamp(140px, 20vw, 188px);
   635:  padding: clamp(20px, 4vw, 34px) clamp(20px, 4vw, 45px);
   636:  align-items: center;
   637:  justify-content: space-between;
   638:  gap: 16px;
   639:  overflow: hidden;
   640:  border-radius: var(--care-radius);
   641:  background-color: var(--care-forest-900);
   642:  background-image: var(--care-garden-image);
   643:  background-position: center 60%;
   644:  background-size: cover;
   645:  background-blend-mode: multiply;
   646:  box-shadow: var(--care-shadow);
   647:  color: var(--care-on-dark);
   648:}
   649:
   650:.care-welcome__copy {
   651:  position: relative;
   652:  z-index: 1;
   653:  min-width: 0;
   654:}
   655:
   656:.care-welcome h1 {
   657:  margin-top: 8px;
   658:  font-size: var(--care-text-page-title);
   659:  line-height: 1.05;
   660:  letter-spacing: -0.035em;
   661:}
   662:
   663:.care-welcome__copy > p:last-child {
   664:  margin-top: 10px;
   665:  color: var(--care-on-dark-soft);
   666:}
   667:
   668:.care-grid {
   669:  display: grid;
   670:  margin-top: var(--care-gap);
   671:  grid-template-columns: minmax(0, 1fr);
   672:  gap: var(--care-gap);
   673:}
   674:
   675:@media (min-width: 900px) {
   676:  .care-grid {
   677:    grid-template-columns: repeat(2, minmax(0, 1fr));
   678:  }
   679:
   680:  .care-grid--alerts {
   681:    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
   682:    align-items: start;
   683:  }
   684:}
   685:
   686:/* ── Cards ── */
   687:.care-card {
   688:  position: relative;
   689:  min-width: 0;
   690:  padding: var(--care-card-pad);
   691:  border: 1px solid var(--care-edge);
   692:  border-radius: var(--care-radius);
   693:  background: var(--care-cream-50);
   694:  box-shadow: var(--care-shadow);
   695:}
   696:
   697:.care-card__heading {
   698:  position: relative;
   699:  z-index: 1;
   700:  display: flex;
   701:  align-items: flex-start;
   702:  justify-content: space-between;
   703:  flex-wrap: wrap;
   704:  gap: 8px 16px;
   705:}
   706:
   707:.care-card__heading h2 {
   708:  margin-top: 6px;
   709:  font-size: var(--care-text-card-title);
   710:  line-height: 1.15;
   711:  letter-spacing: -0.02em;
   712:}
   713:
   714:.care-card__meta {
   715:  color: var(--care-muted);
   716:  font-size: var(--care-text-xs);
   717:}
   718:
   719:.care-badge {
   720:  display: inline-flex;
   721:  min-height: 31px;
   722:  padding: 0 12px;
   723:  align-items: center;
   724:  border-radius: 999px;
   725:  font-size: var(--care-text-xs);
   726:  font-weight: 700;
   727:  white-space: nowrap;
   728:}
   729:
   730:.care-badge--moss { background: var(--care-moss-soft); color: var(--care-forest-900); }
   731:.care-badge--rose { background: var(--care-rose-soft); color: var(--care-rose-ink); }
   732:
   733:/* Today ring */
   734:.care-progress {
   735:  display: flex;
   736:  min-height: 200px;
   737:  padding-top: 20px;
   738:  align-items: center;
   739:  justify-content: center;
   740:  flex-wrap: wrap;
   741:  gap: 20px 40px;
   742:}
   743:
   744:.care-ring {
   745:  display: grid;
   746:  width: clamp(128px, 32vw, 154px);
   747:  aspect-ratio: 1;
   748:  flex: 0 0 auto;
   749:  place-items: center;
   750:  border-radius: 50%;
   751:  background: conic-gradient(var(--care-orange) 0 var(--care-ring-fill), var(--care-cream-200) 0 100%);
   752:  box-shadow: 0 12px 28px rgba(78, 57, 37, 0.13);
   753:}
   754:
   755:.care-ring__center {
   756:  display: flex;
   757:  width: 73%;
   758:  aspect-ratio: 1;
   759:  align-items: center;
   760:  justify-content: center;
   761:  flex-direction: column;
   762:  border-radius: 50%;
   763:  background: var(--care-cream-50);
   764:}
   765:
   766:.care-ring strong {
   767:  color: var(--care-forest-900);
   768:  font-size: 1.4rem;
   769:}
   770:
   771:.care-ring span {
   772:  color: var(--care-muted);
   773:  font-size: var(--care-text-sm);
   774:}
   775:
   776:.care-progress__copy {
   777:  max-width: 220px;
   778:  text-align: center;
   779:}
   780:
   781:.care-progress__copy strong {
   782:  font-size: var(--care-text-lg);
   783:  line-height: 1.3;
   784:}
   785:
   786:.care-progress__copy p {
   787:  margin-top: 8px;
   788:  color: var(--care-muted);
   789:  font-size: var(--care-text-sm);
   790:  line-height: 1.55;
   791:}
   792:
   793:@media (min-width: 520px) {
   794:  .care-progress__copy { text-align: left; }
   795:}
   796:
   797:/* Streak hearts: a rotated square plus two circles, knitted look */
   798:.care-hearts {
   799:  --care-heart-size: clamp(18px, 4.6vw, 32px);
   800:  display: grid;
   801:  min-height: 180px;
   802:  padding-top: 12px;
   803:  align-items: center;
   804:  grid-template-columns: repeat(7, minmax(0, 1fr));
