    75:
    76:      {/* T2-06: Medication editing on /care */}
    77:      <div className="section-title"><h3>{t("care.careToday")}</h3></div>
    78:      <div className="care-grid">
    79:        <article><span><Icon name="check" /></span><strong>{careActivity.dosesTaken}</strong><small>{t("care.dosesTaken")}</small></article>
    80:        <article><span><Icon name="walk" /></span><strong>{careActivity.walkDistance}</strong><small>{t("care.walkedToday")}</small></article>
    81:      </div>
    82:
    83:      <div className="section-title"><h3>Medications</h3></div>
    84:      {loadingMeds ? <p className="supporting">Loading…</p> : medications.length === 0 ? <p className="supporting">No medications yet.</p> : (
    85:        <div className="medication-list">
    86:          {medications.map((med) => (
    87:            <div className="medication-edit-row" key={med.id}>
    88:              {editingMed === med.id ? (
    89:                <div className="medication-edit-form">
    90:                  <strong>{med.name}</strong>
    91:                  {med.strength && <small>{med.strength}</small>}
    92:                  <label>What did your doctor say it's for?</label>
    93:                  <input type="text" value={editPrescribed} onChange={(e) => setEditPrescribed(e.target.value)} placeholder="Your doctor's reason" />
    94:                  <label>Days of supply</label>
    95:                  <input type="number" value={editDays} onChange={(e) => setEditDays(e.target.value)} placeholder="e.g. 30" />
    96:                  <div className="edit-actions">
    97:                    <button className="primary-button" disabled={saving} onClick={() => saveEdit(med.id)}>{saving ? "Saving…" : "Save"}</button>
    98:                    <button className="text-button" onClick={() => setEditingMed(null)}>Cancel</button>
    99:                  </div>
   100:                </div>
   101:              ) : (
   102:                <>
   103:                  <div>
   104:                    <strong>{med.name}</strong>
   105:                    {med.strength && <small> · {med.strength}</small>}
   106:                    {med.prescribedFor && <small><br />Doctor said: {med.prescribedFor}</small>}
   107:                    {med.daysOfSupply !== null && <small> · {med.daysOfSupply} days left</small>}
   108:                  </div>
   109:                  <button className="text-button" onClick={() => startEdit(med)}>Edit</button>
