   119:        <p>{careActivity.description}</p>
   120:      </div>
   121:      <button className="primary-button" onClick={sendTreat}><Icon name="gift" size={20} /> {t("care.sendTreat", { name: dogName })}</button>
   122:    </FullCard>
   123:  );
   124:}
